from datetime import datetime, timedelta

def parse(path):
    ev=[]; cur=None
    for line in open(path):
        line=line.strip()
        if line=='BEGIN:VEVENT': cur={}
        elif line=='END:VEVENT':
            ev.append((datetime.strptime(cur['DTSTART'],'%Y%m%dT%H%M%SZ'),datetime.strptime(cur['DTEND'],'%Y%m%dT%H%M%SZ')))
            cur=None
        elif cur is not None and ':' in line:
            k,v=line.split(':',1); cur[k.split(';')[0]]=v
    return ev

busy={
 'alice':parse('alice_calendar.ics'),
 'bob':parse('bob_calendar.ics'),
 'carol':parse('carol_calendar.ics'),
}

def overlap(s,e,b):
    return any(s < be and e > bs for bs,be in b)

def valid(s,e,day):
    # hard windows
    if s < datetime(2024,1,day,9,0) or e > datetime(2024,1,day,14,0): return False  # Alice hard 9-14
    if s < datetime(2024,1,day,10,0): return False  # Bob no before 10
    if day in (16,18) and e > datetime(2024,1,day,16,30): return False  # Bob Tue/Thu leave
    if e > datetime(2024,1,day,17,0): return False  # Carol 9-17 / Bob afternoon to 5
    # Carol lunch 12:00-12:30
    if s < datetime(2024,1,day,12,30) and e > datetime(2024,1,day,12,0): return False
    for who in busy:
        if overlap(s,e,busy[who]): return False
    return True

for day in range(15,20):
    t=datetime(2024,1,day,9,0)
    while t+timedelta(hours=1) <= datetime(2024,1,day,18,0):
        e=t+timedelta(hours=1)
        if valid(t,e,day):
            print('EARLIEST VALID:', t, '->', e, ['Mon','Tue','Wed','Thu','Fri'][t.weekday()])
            raise SystemExit
        t+=timedelta(minutes=1)
print('none')
EOF
